const toLocalISO = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
const todayISO = () => toLocalISO(new Date());

// meno.priezvisko@matecoslovakia.sk — odstráni diakritiku, zmení na malé písmená
function nameToEmail(fullName, domain = "matecoslovakia.sk") {
  if (!fullName) return "";
  const clean = fullName
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // odstráni diakritiku
    .trim();
  const parts = clean.split(/\s+/).filter(Boolean);
  if (parts.length < 2) return `${clean.toLowerCase()}@${domain}`;
  const first = parts[0].toLowerCase();
  const last = parts[parts.length - 1].toLowerCase();
  return `${first}.${last}@${domain}`;
}

/* ---------------------------------------------------------
   Email — hybridné odosielanie (Outlook Web / mailto pre desktop appku
   alebo mobil). Appka si zapamätá voľbu v prehliadači (localStorage).
--------------------------------------------------------- */
const MAIL_PREF_KEY = "mateco_mail_client_pref"; // "web" | "desktop"
let _mailComposeListener = null;
function setMailComposeListener(fn) {
  _mailComposeListener = fn;
}
function buildMailtoUrl({ to, cc, subject, body }) {
  const parts = [];
  if (cc) parts.push(`cc=${encodeURIComponent(cc)}`);
  if (subject) parts.push(`subject=${encodeURIComponent(subject)}`);
  if (body) parts.push(`body=${encodeURIComponent(body)}`);
  const qs = parts.join("&");
  return `mailto:${to || ""}${qs ? "?" + qs : ""}`;
}
function buildOutlookWebUrl({ to, cc, subject, body }) {
  const parts = [`path=${encodeURIComponent("/mail/action/compose")}`];
  if (to) parts.push(`to=${encodeURIComponent(to)}`);
  if (cc) parts.push(`cc=${encodeURIComponent(cc)}`);
  if (subject) parts.push(`subject=${encodeURIComponent(subject)}`);
  if (body) parts.push(`body=${encodeURIComponent(body)}`);
  return `https://outlook.office.com/mail/deeplink/compose?${parts.join("&")}`;
}
function sendMailWithClient(client, mail) {
  if (client === "web") {
    window.open(buildOutlookWebUrl(mail), "_blank");
  } else {
    window.location.href = buildMailtoUrl(mail);
  }
}
// Zavolajte odkiaľkoľvek v appke: ak už appka pozná preferenciu, mail sa
// rovno otvorí; inak sa najprv opýta (a odpoveď si zapamätá).
function composeMail(mail) {
  let pref = null;
  try {
    pref = localStorage.getItem(MAIL_PREF_KEY);
  } catch (e) {
    console.error("localStorage nedostupný, appka sa opýta znova", e);
  }
  if (pref === "web" || pref === "desktop") {
    sendMailWithClient(pref, mail);
  } else if (_mailComposeListener) {
    _mailComposeListener(mail);
  } else {
    console.error("composeMail: mailComposeListener ešte nie je zaregistrovaný");
  }
}

const addDaysISO = (iso, days) => {
  const d = new Date(iso + "T00:00:00");
  const shifted = new Date(d.getTime() + days * 86400000);
  return toLocalISO(shifted);
};
function compressDates(dates) {
  const sorted = [...dates].sort();
  if (sorted.length === 0) return "";
  const ranges = [];
  let start = sorted[0], prev = sorted[0];
  for (let i = 1; i < sorted.length; i++) {
    const d = sorted[i];
    if (d === addDaysISO(prev, 1)) { prev = d; continue; }
    ranges.push(start === prev ? fmtDate(start) : `${fmtDate(start)}–${fmtDate(prev)}`);
    start = d; prev = d;
  }
  ranges.push(start === prev ? fmtDate(start) : `${fmtDate(start)}–${fmtDate(prev)}`);
  return ranges.join(", ");
}
function weekRangeFor(iso) {
  const d = new Date(iso + "T00:00:00");
  const dow = d.getDay();
  const mondayOffset = dow === 0 ? -6 : 1 - dow;
  const weekStart = addDaysISO(iso, mondayOffset);
  const weekEnd = addDaysISO(weekStart, 6);
  return { weekStart, weekEnd };
}
const fmtDate = (iso) => {
  if (!iso) return "—";
  const [y, m, d] = iso.split("-");
  return `${d}.${m}.${y}`;
};
const daysBetween = (a, b) => {
  const d1 = new Date(a + "T00:00:00");
  const d2 = new Date(b + "T00:00:00");
  return Math.round((d2 - d1) / 86400000);
};
const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);

function effectiveStatus(job, today) {
  if (!job) return null;
  if (job.status === "completed") return "completed";
  if (today < job.startDate) return "planned";
  if (job.endDate && today > job.endDate) return "overdue";
  return "active";
}

function currentJobFor(jobs, machineId, today) {
  const candidates = jobs
    .filter((j) => j.machineId === machineId && j.status !== "completed")
    .filter((j) => j.startDate <= today)
    .sort((a, b) => (a.startDate < b.startDate ? 1 : -1));
  return candidates[0] || null;
}
// Aktuálne miesto stroja PRÁVE TERAZ — podľa bežiacej zákazky, inak podľa depa.
// Používa sa všade, kde sa má zobrazovať živá poloha (poškodenia, revízie, úradné
// skúšky, plán servisu), namiesto adresy "zamrznutej" v momente nahlásenia.
function machineCurrentLocation(machine) {
  if (!machine) return "";
  return machine.currentJob?.toLocation || machine.depo || "";
}
// To isté pre priradenia v Pláne servisu — uprednostní živú polohu stroja (ak ho
// vieme dohľadať), inak sa vráti k pôvodne uloženej hodnote (napr. rýchle udalosti
// bez stroja, alebo externý stroj mimo evidencie).
function assignmentLocation(a, machineById) {
  if (a.machineId) {
    const live = machineCurrentLocation(machineById?.[a.machineId]);
    if (live) return live;
  }
  return a.umiestnenie || "";
}
function nextJobFor(jobs, machineId, today) {
  const candidates = jobs
    .filter((j) => j.machineId === machineId && j.status !== "completed")
    .filter((j) => j.startDate > today)
    .sort((a, b) => (a.startDate > b.startDate ? 1 : -1));
  return candidates[0] || null;
}

