/* ---------------------------------------------------------
   Resolve damage modal (Označiť ako vyriešené — dátum opravy + komentár)
--------------------------------------------------------- */
function ResolveDamageModal({ damage, today, onClose, onSave }) {
  const options = [
    { id: "opravene", label: "Opravené" },
    { id: "dalsi_zasah", label: "Potrebný ďalší servisný zásah" },
    { id: "caka_diely", label: "Čaká na diely" },
    { id: "zavazna_porucha", label: "Závažná porucha" },
  ];
  const [stav, setStav] = useState(damage.stav || (damage.resolved ? "opravene" : options[0].id));
  const [date, setDate] = useState(damage.opravaDatum || today);
  const [comment, setComment] = useState(damage.opravaKomentar || "");
  const canSave = stav && date && comment.trim();
  return (
    <Modal title={`Upraviť stav zákazky · ${damage.code}`} onClose={onClose}>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 10 }}>{damage.popis}</div>
      <Field label="Stav *">
        <select value={stav} onChange={(e) => setStav(e.target.value)} style={{ width: "100%" }}>
          {options.map((o) => <option key={o.id} value={o.id}>{o.label}</option>)}
        </select>
      </Field>
      <Field label="Dátum *">
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ width: "100%" }} />
      </Field>
      <Field label="Čo sa zistilo / vykonalo *">
        <textarea value={comment} onChange={(e) => setComment(e.target.value)} rows={3} placeholder="Popis zásahu…" style={{ width: "100%" }} />
      </Field>
      <button className="btn btn-accent" disabled={!canSave} onClick={() => onSave(stav, date, comment.trim())}>
        Uložiť
      </button>
    </Modal>
  );
}

/* ---------------------------------------------------------
   Damage resolution modal (read-only view from machine card history)
--------------------------------------------------------- */
function DamageResolutionModal({ damage, technicianById, protocolLogs, onClose, onBack }) {
  const d = damage;
  const isSimple = d.type === "revizia" || d.type === "uradnaSkuska";
  const techIds = d.technicianIds && d.technicianIds.length ? d.technicianIds : (d.technicianId ? [d.technicianId] : []);
  const techNames = techIds.map((id) => technicianById?.[id]?.name).filter(Boolean).join(", ");

  if (!d.resolved) {
    // Nové / Pridelené — len na čítanie. Reálne pridelenie sa dá robiť
    // len zo záložky Poškodenia/Externé, kde sú práva nastavené správne.
    const stavLabel = techIds.length ? "Pridelené" : "Nové";
    return (
      <Modal title={`${stavLabel} · ${d.code}`} onClose={onClose}>
        {onBack && (
          <button className="btn btn-ghost" style={{ marginBottom: 14 }} onClick={onBack}>
            ← Späť na kartu stroja
          </button>
        )}
        <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", border: "1px solid var(--border)", borderRadius: 8, overflow: "hidden", marginBottom: 14 }}>
          <CardField label="Nahlásené" value={fmtDate(d.dateReported)} />
          <CardField label="Stav" value={stavLabel} danger={!techIds.length} />
          <CardField label="Pridelené komu" value={techNames || "— zatiaľ nikomu —"} />
          <CardField label="Na kedy" value={d.assignedDate ? fmtDate(d.assignedDate) : null} />
        </div>
        <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>Popis</div>
        <div style={{ fontSize: 13 }}>{d.popis}</div>
      </Modal>
    );
  }

  const title = d.type === "revizia" ? "Revízia vykonaná" : d.type === "uradnaSkuska" ? "Úradná skúška vykonaná" : "Poškodenie vyriešené";
  const doneDate = d.opravaDatum || d.vykonanaDatum;
  return (
    <Modal title={`${title} · ${d.code}`} onClose={onClose}>
      {onBack && (
        <button className="btn btn-ghost" style={{ marginBottom: 14 }} onClick={onBack}>
          ← Späť na kartu stroja
        </button>
      )}
      <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", border: "1px solid var(--border)", borderRadius: 8, overflow: "hidden", marginBottom: 14 }}>
        <CardField label="Nahlásené" value={fmtDate(d.dateReported)} />
        <CardField label={isSimple ? "Dátum vykonania" : "Dátum opravy"} value={doneDate ? fmtDate(doneDate) : null} />
      </div>
      <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>Pôvodný popis</div>
      <div style={{ fontSize: 13, marginBottom: 14 }}>{d.popis}</div>
      {!isSimple && (
        <>
          <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>Čo sa opravilo</div>
          <div style={{ fontSize: 13 }}>{d.opravaKomentar || "— bez komentára —"}</div>
        </>
      )}
      {(protocolLogs || []).filter((p) => p.damageId === d.id).map((p) => (
        <div key={p.id} style={{ marginTop: 14 }}>
          <div style={{ fontSize: 12, color: "var(--text-dim)", marginBottom: 4 }}>
            Vypísaný protokol — {p.technicianName || "—"} ({fmtDate(p.createdAt)})
          </div>
          <a href={p.imageUrl} target="_blank" rel="noreferrer">
            <img src={p.imageUrl} alt="Protokol" style={{ maxWidth: "100%", border: "1px solid var(--border)", borderRadius: 6 }} />
          </a>
        </div>
      ))}
    </Modal>
  );
}

